# What Gwyddion offers directly in its right-click menu, kept at the top of
# the list so the everyday choices are not buried among the sixty names.
FAVOURITES = (
    "Gray", "Gwyddion.net", "Gold", "Body", "Sky", "Spring", "Cold", "Warm",
    "Rainbow1", "Rainbow2", "Viridis", "Spectral", "BW1", "Gray-inverted",
)

# The gradient the viewer starts with: Gwyddion's own house palette, which is
# what this project has always drawn with.
DEFAULT = "Gwyddion.net"

_cache = {}
_current = DEFAULT


def names():
    """All gradient names, the common ones first, then the rest A-Z."""
    rest = sorted((n for n in GRADIENTS if n not in FAVOURITES), key=str.lower)
    return [n for n in FAVOURITES if n in GRADIENTS] + rest


def get(name=None):
    """The colormap for `name`.

    Accepts a Gwyddion gradient name, a matplotlib colormap name, or a
    colormap object (returned unchanged).  Anything unknown falls back to the
    default gradient rather than raising, so a stale name in a saved setting
    cannot stop the window from drawing.
    """
    if name is None:
        return get(_current)
    if isinstance(name, mcolors.Colormap):
        return name
    if name in _cache:
        return _cache[name]
    stops = GRADIENTS.get(name)
    if stops is not None:
        cmap = mcolors.LinearSegmentedColormap.from_list(
            name, [(p, (r, g, b)) for p, r, g, b in stops])
    else:
        try:
            cmap = matplotlib.colormaps[name]
        except KeyError:
            return get(DEFAULT)
    _cache[name] = cmap
    return cmap


def current():
    """The colormap currently selected for topography images."""
    return get(_current)


def current_name():
    return _current


def set_current(name):
    """Select the gradient used for topography images from now on."""
    global _current
    if name in GRADIENTS or name in matplotlib.colormaps:
        _current = name
    return _current
